<?php
require_once __DIR__.'/includes/functions.php';require_customer();$uid=(int)current_user()['id'];$s=$conn->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY created_at DESC');$s->bind_param('i',$uid);$s->execute();$orders=$s->get_result()->fetch_all(MYSQLI_ASSOC);render_header('My orders');?><div class="page-heading"><span class="eyebrow">YOUR SHOPPING HISTORY</span><h1>My orders</h1><p class="muted">Track your order and payment status here.</p></div><?php if(!$orders):?><div class="empty-state"><div class="empty-icon">📦</div><h2>No orders yet</h2><a class="button" href="<?=e(url())?>">Start shopping</a></div><?php else:?><div class="orders-list"><?php foreach($orders as $o):?><article class="order-card"><div class="order-head"><div><small>ORDER NUMBER</small><b><?=e($o['order_number'])?></b><small><?=e(date('d M Y, h:i A',strtotime($o['created_at'])))?></small></div><span class="status-pill"><?=e(str_replace('_',' ',$o['status']))?></span></div><div class="order-meta"><span>Payment: <b><?=e(strtoupper($o['payment_method']))?></b></span><span>Payment status: <b><?=e(str_replace('_',' ',$o['payment_status']))?></b></span><strong><?=money($o['total'])?></strong></div><?php if($o['payment_method']==='upi'&&in_array($o['payment_status'],['pending','rejected'],true)):?><a class="button small" href="<?=e(url('payment.php?order='.$o['id']))?>"><?=($o['payment_status']==='rejected'?'Resubmit payment details':'Submit payment details')?></a><?php endif;?><?php if($o['admin_note']):?><p class="muted">Store note: <?=e($o['admin_note'])?></p><?php endif;?><details><summary>Order details</summary><?php $s2=$conn->prepare('SELECT product_name,unit_price,quantity FROM order_items WHERE order_id=?');$s2->bind_param('i',$o['id']);$s2->execute();foreach($s2->get_result() as $it):?><p><?=e($it['product_name'])?> × <?=$it['quantity']?> — <?=money($it['unit_price']*$it['quantity'])?></p><?php endforeach;?><p><?=e($o['address'])?>, PIN <?=e($o['pincode'])?></p></details></article><?php endforeach;?></div><?php endif;?><?php render_footer();?>
